/* Cosecha · personas: Productores, Equipo y permisos, Mi zona, Mi portal (comprador), WhatsApp (lo que recibe el productor), Mercado. Datos FICTICIOS. */
(() => {
  const { $, $$, esc, ic, CRC, KG, chip, nextThu, fdate, D, C, ROLES, MODS } = window.Cosecha;
  const S = window.Cosecha.S, V = window.Cosecha.views, CHN = { wa: "WhatsApp", call: "Llamada", voice: "Nota de voz", link: "Enlace de zona" };
  const P = { sel: null, users: D.users.map(([n, r]) => ({ n, r, st: "activo" })), audit: D.audit.slice(), chatP: "p1", bh: 3, cf: { kg: "", cause: "oscurecimiento", photos: 0, note: "" }, zoneSent: {} };
  const CHATHEAD = '<div class="row sp"><b>Lo que recibe el productor</b><button class="btn alt sm" data-close>Cerrar</button></div>';
  const R = () => window.Cosecha.render(), log = (t) => P.audit.unshift(`2026-10-24 · ${ROLES.find((r) => r.id === C.role).short} (usted) ${t}`);

  V.productores = () => `<table class="tbl"><thead><tr><th>Productor</th><th class="r">Finca</th><th class="r">Capacidad</th><th>Cómo se le habla</th><th>Equidad</th><th>Estimación</th><th>Pago</th><th></th></tr></thead><tbody>${S.prod.map((p) => `<tr><td><b>${esc(p.name)}</b><br><span class="mut">${esc(p.zone)}</span></td><td class="r">${p.ha} ha</td><td class="r">${KG(p.w)}</td>
    <td><select data-a="ppl:ch" data-id="${p.id}" aria-label="Canal de ${esc(p.name)}">${Object.entries(CHN).map(([k, t]) => `<option value="${k}" ${p.ch === k ? "selected" : ""}>${t}</option>`).join("")}</select></td><td>${p.def > 0.05 ? chip("ok", "plus", `+${Math.round(p.def * 50)} % próximo reparto`) : p.def < -0.05 ? chip("n", "check", `${Math.round(p.def * 50)} %`) : '<span class="mut">equilibrado</span>'}</td>
    <td>${chip(p.upd > 7 ? "warn" : "ok", p.upd > 7 ? "clock" : "check", `hace ${p.upd} d`)}</td><td>${p.sinpe === "—" ? chip("warn", "warn", "Sin SINPE") : esc(p.sinpe)}</td><td><button class="btn alt sm" data-a="ppl:sel" data-id="${p.id}">Ver ficha</button></td></tr>`).join("")}</tbody></table>
    <p class="mut">Los productores no instalan nada: usted elige por dónde se les habla. Mensajes <b>de usted</b>, de no más de 3 líneas y siempre desde el mismo número.</p>`;
  const drawer = (p) => { const r = window.Cosecha.pool().rows.find((x) => x.id === p.id), fair = Math.round((p.w / S.prod.reduce((a, x) => a + x.w, 0)) * 480);
    return `<div class="row sp"><b style="font-size:1.1rem">${esc(p.name)} · ${esc(p.zone)}</b><button class="btn alt sm" data-close>Cerrar</button></div><dl class="kv" style="margin-top:.6rem"><dt>Finca</dt><dd>${p.ha} ha · capacidad ${KG(p.w)}</dd><dt>Canal</dt><dd>${CHN[p.ch]}</dd><dt>Teléfono</dt><dd>${esc(p.phone)}</dd><dt>SINPE</dt><dd>${esc(p.sinpe)}</dd><dt>Consentimiento</dt><dd>${chip("ok", "check", "Datos y mensajes autorizados")}</dd></dl>
    <h2>Libro de equidad</h2><p class="mut">Parte justa del último envío: ${KG(fair)}. ${p.def > 0 ? "Quedó corto antes: el próximo reparto lo compensa." : p.def < 0 ? "Recibió de más antes: el próximo reparto lo equilibra." : "Está equilibrado."}</p>
    ${r ? `<h2>Última entrega</h2><dl class="kv"><dt>Kilos A / B</dt><dd>${r.a} / ${r.b}</dd><dt>Total del pool</dt><dd>${CRC(r.total)}</dd><dt>Anticipo</dt><dd>${CRC(r.adv)}</dd><dt>Saldo</dt><dd>${CRC(r.saldo)}</dd></dl>` : ""}<p><button class="btn" data-a="ppl:chatfor" data-id="${p.id}">Ver lo que recibe por WhatsApp</button></p>`; };

  V.equipo = () => { const ext = ["comprador", "enlace", "productor"], internal = ROLES.filter((r) => !ext.includes(r.id));
    return `<div class="cols2"><div><h2 style="margin-top:0">Quién tiene acceso</h2><table class="tbl"><thead><tr><th>Persona</th><th>Rol</th><th>Estado</th><th></th></tr></thead><tbody>${P.users.map((u, i) => `<tr><td>${esc(u.n)}</td><td><select data-a="ppl:urole" data-i="${i}" ${u.r === "owner" ? "disabled" : ""} aria-label="Rol de ${esc(u.n)}">${internal.map((r) => `<option value="${r.id}" ${u.r === r.id ? "selected" : ""} ${r.id === "owner" ? "disabled" : ""}>${r.short}</option>`).join("")}</select></td><td>${chip(u.st === "activo" ? "ok" : "warn", u.st === "activo" ? "check" : "clock", u.st)}</td><td>${u.r !== "owner" ? `<button class="btn alt sm" data-a="ppl:view" data-id="${u.r}">Ver como</button> <button class="btn alt sm" data-a="ppl:rev" data-i="${i}">Revocar</button>` : ""}</td></tr>`).join("")}</tbody></table>
      <h2>Invitar a alguien</h2><div class="card"><div class="grid2"><label class="f">Correo<input type="text" data-f="iv-m" data-a="ppl:ivm" placeholder="persona@ejemplo.cr"></label><label class="f">Rol<select data-a="ppl:ivr">${internal.filter((r) => r.id !== "owner").map((r) => `<option value="${r.id}">${r.short}</option>`).join("")}</select></label><label class="f">El acceso vence<select data-a="ppl:ive"><option>en 7 días</option><option>al final de la temporada</option><option>no vence</option></select></label></div><button class="btn" data-a="ppl:inv">Enviar invitación</button><p class="mut">Solo el propietario concede acceso. Antes de invitar, use «Ver como» para comprobar lo que verá cada rol.</p></div></div>
      <aside class="summ"><div class="card"><h2 style="margin-top:0">Auditoría</h2><ul class="mut" style="margin:0;padding-left:1.1rem">${P.audit.slice(0, 8).map((a) => `<li>${esc(a)}</li>`).join("")}</ul></div></aside></div>
      <h2>Qué ve cada rol</h2><table class="tbl"><thead><tr><th>Módulo</th>${ROLES.map((r) => `<th>${r.short}</th>`).join("")}</tr></thead><tbody>${MODS.filter((m) => m.id !== "__more").map((m) => `<tr><td>${esc(m.t)}</td>${ROLES.map((r) => `<td>${m.roles.includes(r.id) ? '<span class="dot-ok">✓</span>' : '<span class="mut">—</span>'}</td>`).join("")}</tr>`).join("")}</tbody></table>
      <p class="mut">Mínimo privilegio: nadie ve más de lo que necesita. Solo el propietario ve «Equipo y permisos». Acopio y transportista nunca ven precios; Comercial nunca ve pagos a productores.</p>`; };

  V.zona = () => { const mine = S.prod.filter((p) => /Corredores|Osa/.test(p.zone));
    return `<p class="mut">Usted es el <b>enlace de zona</b> de Corredores y Osa: ayuda a que lleguen los avisos a quienes no usan WhatsApp. Ve fechas y cantidades, <b>no montos</b>.</p><div class="stack">${mine.map((p) => `<div class="card row sp"><span><b>${esc(p.name)}</b> <span class="mut">· ${esc(p.zone)} · ${CHN[p.ch]}</span><br>Envío del ${fdate(nextThu())}: <b>${KG(p.w * 0.75)}</b></span><span class="row">${p.ch === "link" || p.ch === "call" ? (P.zoneSent[p.id] ? chip("ok", "check", "Avisado") : `<button class="btn sm" data-a="ppl:avisar" data-id="${p.id}">${ic("users")} Ya le avisé</button>`) : chip("n", "chat", "Le llega por WhatsApp")}</span></div>`).join("")}</div><p class="mut">Cada aviso queda registrado con su nombre. Si alguien no puede, avise al gestor de inmediato.</p>`; };

  V.portal = () => { const o = S.orders[1], rem = 8 - P.bh, ok = rem >= 0, cf = P.cf, bars = [["3 nov", 240], ["10 nov", 120], ["17 nov", 0], ["24 nov", 0]];
    return `<div class="cols2"><div><h2 style="margin-top:0">Mis pedidos</h2><div class="card row sp"><span><b>${esc(o.buyer)}</b><br><span class="mut">Entrega del ${fdate(nextThu())} · ${KG(o.kg)}</span></span>${chip("ok", "check", "Confirmado")}</div>
      <h2>Oferta semanal prometible</h2><div class="card">${bars.map(([w, kg]) => `<div class="wk"><span>${w}</span><div class="bar" aria-hidden="true"><i style="width:${(kg / 800) * 100}%"></i></div><b>~${Math.round((kg * 0.8) / 10) * 10} kg</b></div>`).join("")}<p class="mut">Es lo que la asociación puede prometer con seguridad. Le avisaremos <b>antes</b> si algo cambia.</p></div>
      <h2>Ficha de calidad</h2><div class="card grid2"><div><b>${chip("ok", "check", "Aceptable")}</b><ul class="mut"><li>Cáscara roja uniforme</li><li>Espinas verdes o amarillentas, firmes</li><li>Pulpa blanca, sin olor fermentado</li></ul></div><div><b>${chip("bad", "x", "No aceptable")}</b><ul class="mut"><li>Moho o pudrición</li><li>Espinas negras y secas</li><li>Golpes que abren la cáscara</li></ul></div></div></div>
      <aside class="summ"><div class="card"><h2 style="margin-top:0">Reportar un problema</h2><label class="f">Recibió la entrega hace (horas)<input type="number" inputmode="decimal" value="${P.bh}" data-a="ppl:bh" data-f="bh"></label><p>${chip(ok ? "warn" : "bad", ok ? "clock" : "warn", ok ? `Le quedan ${rem} h para reclamar` : "Pasó la ventana de 8 horas")}</p>
        ${ok ? `<label class="f">Kilos afectados<input type="number" inputmode="decimal" value="${cf.kg}" data-a="ppl:cfk" data-f="cfk"></label><label class="f">Qué vio<select data-a="ppl:cfc"><option value="oscurecimiento" ${cf.cause === "oscurecimiento" ? "selected" : ""}>Espinas oscuras</option><option value="golpes" ${cf.cause === "golpes" ? "selected" : ""}>Golpes</option><option value="hongo" ${cf.cause === "hongo" ? "selected" : ""}>Moho o pudrición</option></select></label>
        <p class="mut" style="margin:.4rem 0">Fotos (se necesitan 3)</p><div class="row">${["Caja con etiqueta", "Fruta afectada", "Balanza"].map((t, i) => `<button class="btn alt sm" data-a="ppl:cfp" data-i="${i}" aria-pressed="${cf.photos > i}">${ic("cam")} ${t}${cf.photos > i ? " ✓" : ""}</button>`).join("")}</div><p><button class="btn" data-a="ppl:cfs" ${+cf.kg > 0 && cf.photos >= 3 ? "" : "disabled"}>Enviar reclamo</button></p>` : '<p class="mut">Pasadas 8 horas desde la recepción la entrega se considera aceptada. Si hay un defecto oculto, escriba a la asociación y se revisará el caso.</p>'}</div></aside></div>`; };

  V.chat = () => { const p = S.prod.find((x) => x.id === P.chatP), r = window.Cosecha.pool().rows.find((x) => x.id === p.id) || window.Cosecha.pool().rows[0], kg = 92, msg = `Buenos días, ${p.name}. Para el ${fdate(nextThu())} le pedimos ${kg} kg de mamón chino. ¿Nos confirma? Responda 1 si puede o 2 si no puede.`;
    const first = { wa: `<div class="bub">${esc(msg)}<small>6:31</small></div><div class="bub me">1<small>6:40 ✓✓</small></div>`, call: `<div class="bub"><b>Llamada perdida</b> de «Asociación (ejemplo)»<small>6:31</small></div><div class="bub me">Le devuelvo la llamada, don.<small>6:50</small></div>`, voice: `<div class="bub">${ic("mic")} <b>Nota de voz · 0:19</b><br><span class="mut">«${esc(msg)}»</span><small>6:31</small></div><div class="bub me">${ic("mic")} Nota de voz · 0:04<small>6:44 ✓✓</small></div>`, link: `<div class="bub"><b>Mensaje llevado por su enlace de zona</b><br>«${esc(msg)}»<small>Don Beto no usa WhatsApp</small></div>` }[p.ch];
    return `<p class="mut" style="text-align:center">Lo que recibe <b>${esc(p.name)}</b> (canal: ${CHN[p.ch]}). No instala nada.</p><div class="row" style="justify-content:center;margin-bottom:.4rem"><select data-a="ppl:chatp" style="max-width:18rem" aria-label="Ver como productor">${S.prod.map((x) => `<option value="${x.id}" ${x.id === P.chatP ? "selected" : ""}>${esc(x.name)} · ${CHN[x.ch]}</option>`).join("")}</select></div>
    <div class="pwa"><div class="hd">Asociación (ejemplo) · 8888-0000</div><div class="msgs">${first}
      <div class="bub"><b>Recibo de hoy</b><br>Recibimos <span class="big">90 kg</span><br>Aceptados: <b>80 kg</b> · rechazados 10 kg (golpeado)<br>Anticipo estimado: <b>${CRC(Math.round(80 * 800 * 0.6))}</b>. Se paga el <b>viernes</b>.<small>15:12</small></div>
      <div class="bub"><b>Estado de cuenta</b><br>Entregó: ${r.a + r.b} kg<br>Ya se le pagó: <b>${CRC(r.adv + r.emer)}</b><br>Falta: <b>${CRC(Math.max(0, r.saldo))}</b> (se paga al cerrar la semana)<br><span class="mut">¿Dudas? Responda a este mensaje.</span><small>Vie 8:00</small></div></div></div>
    <p class="mut" style="text-align:center">Reglas: de usted · máximo 3 líneas · siempre el mismo número guardado · sin enlaces ni apps · la idea principal primero.</p>`; };

  V.mercado = () => { const M = window.CosechaMarket, tabs = [["ruta", "Ruta de arranque"], ["pipeline", "Seguimiento de compradores"], ["secuencia", "Contacto"], ["kit", "Kit comercial"]];
    return `<div class="seg" role="tablist" aria-label="Mercado">${tabs.map(([v, t]) => `<button class="btn ${M.S.v === v ? "" : "alt"} sm" data-v="${v}" role="tab" aria-selected="${M.S.v === v}">${t}</button>`).join("")}</div>${M.V[M.S.v]()}`; };

  window.Cosecha.handlers.push((type, e) => {
    const t = e.target.closest("[data-a]"); if (!t || !t.dataset.a.startsWith("ppl:")) return false; const a = t.dataset.a, id = t.dataset.id, v = e.target.value;
    if (type === "click") {
      if (a === "ppl:sel") { const p = S.prod.find((x) => x.id === id), sh = $("#sheet"); sh.hidden = false; sh.innerHTML = drawer(p); return true; }
      if (a === "ppl:chatfor") { P.chatP = id; $("#sheet").innerHTML = CHATHEAD + V.chat(); return true; }
      if (a === "ppl:view") { DevKit.setRole(id); return true; }
      if (a === "ppl:rev") { const u = P.users[+t.dataset.i]; u.st = "revocado"; log(`revocó el acceso de ${u.n}`); window.Cosecha.toast("Acceso revocado de inmediato"); R(); return true; }
      if (a === "ppl:inv") { const m = $('[data-a="ppl:ivm"]').value.trim(), r = $('[data-a="ppl:ivr"]').value; if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(m)) { window.Cosecha.toast("Escriba un correo válido"); return true; } P.users.push({ n: m, r, st: "invitado" }); log(`invitó a ${m} como ${r}`); window.Cosecha.toast("Invitación enviada"); R(); return true; }
      if (a === "ppl:avisar") { P.zoneSent[id] = true; window.Cosecha.toast("Aviso registrado a su nombre"); R(); return true; }
      if (a === "ppl:cfp") { P.cf.photos = +t.dataset.i + 1 === P.cf.photos ? +t.dataset.i : +t.dataset.i + 1; R(); return true; }
      if (a === "ppl:cfs") { S.claims.unshift({ id: "c" + (S.claims.length + 1), buyer: S.orders[1].buyer, lot: "RB-261024-P1", kg: 200, aff: +P.cf.kg, cause: P.cf.cause, hours: P.bh, photos: P.cf.photos, st: "nuevo", note: "Reclamo enviado desde el portal." }); P.cf = { kg: "", cause: "oscurecimiento", photos: 0, note: "" }; window.Cosecha.toast("Reclamo enviado dentro de la ventana. La asociación responde en 2 horas hábiles."); R(); return true; }
      return false;
    }
    if (a === "ppl:ch" && type === "change") { S.prod.find((p) => p.id === id).ch = v; R(); return true; }
    if (a === "ppl:urole" && type === "change") { const u = P.users[+t.dataset.i], prev = u.r; u.r = v; log(`cambió el rol de ${u.n}: ${prev} → ${v}`); window.Cosecha.toast("Rol actualizado y auditado"); R(); return true; }
    if (a === "ppl:chatp" && type === "change") { P.chatP = v; R(); const sh = $("#sheet"); if (!sh.hidden && sh.querySelector(".pwa")) sh.innerHTML = CHATHEAD + V.chat(); return true; }
    if (a === "ppl:cfc" && type === "change") { P.cf.cause = v; R(); return true; }
    if (type === "input") { if (a === "ppl:bh") { P.bh = Math.max(0, +v || 0); R(); return true; } if (a === "ppl:cfk") { P.cf.kg = v; R(); return true; } if (a === "ppl:ivm") return true; }
    return false;
  });
})();
